CREATE POLICY "Users can delete own cart items" ON public.cart_items AS PERMISSIVE FOR DELETE TO authenticated USING ((EXISTS ( SELECT 1
FROM carts
WHERE ((carts.id = cart_items.cart_id) AND (carts.user_id = auth.uid())))));

CREATE POLICY "Users can insert into own cart items" ON public.cart_items AS PERMISSIVE FOR INSERT TO authenticated WITH CHECK ((EXISTS ( SELECT 1
FROM carts
WHERE ((carts.id = cart_items.cart_id) AND (carts.user_id = auth.uid())))));

CREATE POLICY "Users can manage own cart items" ON public.cart_items AS PERMISSIVE FOR ALL TO public USING ((cart_id IN ( SELECT carts.id
FROM carts
WHERE (carts.user_id = auth.uid()))));

CREATE POLICY "Users can view own cart items" ON public.cart_items AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
FROM carts
WHERE ((carts.id = cart_items.cart_id) AND (carts.user_id = auth.uid())))));

CREATE POLICY cart_items_owner ON public.cart_items AS PERMISSIVE FOR ALL TO public USING ((cart_id IN ( SELECT carts.id
FROM carts
WHERE (carts.user_id = auth.uid()))));

CREATE POLICY order_items_select_own ON public.order_items AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
FROM orders
WHERE ((orders.id = order_items.order_id) AND (orders.customer_id = auth.uid())))));

CREATE POLICY "Admins can read system settings" ON public.system_settings AS PERMISSIVE FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
FROM users u
WHERE ((u.id = auth.uid()) AND (u.is_active = true) AND (u.role = 'admin'::text)))));
